sys_ui_action.client_script_v2:
function onClick() {
    g_form.setValue('x_ustgl_insighti_0_next_best_action', '');
    g_form.addInfoMessage('Generating Next Best Action...');
    var ga = new GlideAjax('x_ustgl_insighti_0.NBAGeneration');
    ga.addParam('sysparm_name', 'generateNBA');
    ga.addParam('sysparm_sys_id', g_form.getUniqueValue());
    ga.addParam('sysparm_table', g_form.getTableName());


    ga.getXMLAnswer(function(response) {

        g_form.clearMessages();
        if (!response) {
            g_form.addErrorMessage('Failed to generate Next Best Action');
            return;
        }

        if (response.startsWith("ERROR:")) {
            g_form.addErrorMessage(response.replace("ERROR:", ""));
            return;
        }

        g_form.setValue('x_ustgl_insighti_0_next_best_action', response);

        // Save (Workspace + Classic)
        if (typeof g_form.saveRecord === 'function') {
            g_form.saveRecord();
        } else {
            g_form.save();
        }
        g_form.addInfoMessage('Next Best Action generated successfully');

    });
}

